// Mirror the native All In availability; never take ownership of its eligibility.
export async function mountAllInHelp(machine) {
  await customElements.whenDefined('app-all-in-machine-control');
  const host=machine.querySelector('app-all-in-machine-control');
  if(!host)return;
  const help=document.createElement('a');
  help.className='site-how-to-play';
  help.href='/learn/tutorial/';
  help.setAttribute('aria-label','How to play Degenerus');
  help.innerHTML='<span>HOW<br>TO PLAY</span>';
  help.hidden=true;
  host.append(help);
  function sync(){
    const button=host.querySelector('[data-bind="all-in-machine-button"]');
    if(!button)return;
    const unavailable=button.hidden||button.disabled;
    host.toggleAttribute('data-site-help',unavailable);
    if(help.hidden===unavailable)help.hidden=!unavailable;
  }
  new MutationObserver(sync).observe(host,{subtree:true,attributes:true,attributeFilter:['hidden','disabled'],childList:true});
  sync();
}
